1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;
9	
10	/**
11	 * Rejects a create-owner request whose lower-cased email is already used by any other
12	 * owner, with a 409 Conflict. An absent (null/blank) email is not a conflict. Runs after
13	 * {@link BuildOwner} has normalized the email.
14	 */
15	public class CheckOwnerEmailUnique {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
18	            throws DuplicateEmailException {
19	        String email = key(owner.getEmail());
20	        if (email.isEmpty()) {
21	            return; // no email supplied: nothing to conflict with
22	        }
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
25	                continue; // same record (e.g. re-save), not a conflict
26	            }
27	            if (email.equals(key(existing.getEmail()))) {
28	                throw new DuplicateEmailException(owner.getEmail());
29	            }
30	        }
31	    }
32	
33	    /** Comparison key: lower-cased and trimmed; a null email becomes empty. */
34	    private static String key(String value) {
35	        if (value == null) {
36	            return "";
37	        }
38	        return value.strip().toLowerCase(Locale.ROOT);
39	    }
40	}
