26	/**
27	 * Simple JavaBean domain object representing an owner.
28	 *
29	 * @author Ken Krebs
30	 * @author Juergen Hoeller
31	 * @author Sam Brannen
32	 * @author Michael Isvy
33	 */
34	@Entity
35	@Table(name = "owners")
36	public class Owner extends Person {
37	    @Column(name = "address")
38	    @NotEmpty
39	    private String address;
40	
41	    @Column(name = "city")
42	    @NotEmpty
43	    private String city;
44	
45	    @Column(name = "telephone")
46	    @NotEmpty
47	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 form: '+' followed by 8 to 15 digits")
48	    private String telephone;
49	
50	    @Column(name = "email")
51	    private String email;
52	
53	    @Column(name = "registration_date", columnDefinition = "DATE")
54	    private java.time.LocalDate registrationDate;
55	
56	    @Column(name = "customer_code")
57	    private String customerCode;
58	
59	    @Column(name = "household_id")
60	    private String householdId;
61	
62	    @Column(name = "namesake_count")
63	    private Integer namesakeCount;
64	
65	    @Column(name = "household_size")
66	    private Integer householdSize;
67	
68	    @Column(name = "bulk_signup_warning")
69	    private boolean bulkSignupWarning;
70	
71	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
72	    private Set<Pet> pets;
73	
74	    public String getAddress() {
75	        return this.address;
76	    }
77	
78	    public void setAddress(String address) {
79	        this.address = address;
80	    }
81	
82	    public String getCity() {
83	        return this.city;
84	    }
85	
86	    public void setCity(String city) {
87	        this.city = city;
88	    }
89	
90	    public String getTelephone() {
91	        return this.telephone;
92	    }
93	
94	    public void setTelephone(String telephone) {
95	        this.telephone = telephone;
96	    }
97	
98	    public String getEmail() {
99	        return this.email;
100	    }
101	
102	    public void setEmail(String email) {
103	        this.email = email;
104	    }
105	
106	    public java.time.LocalDate getRegistrationDate() {
107	        return this.registrationDate;
108	    }
109	
110	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
111	        this.registrationDate = registrationDate;
112	    }
113	
114	    public String getCustomerCode() {
115	        return this.customerCode;
116	    }
117	
118	    public void setCustomerCode(String customerCode) {
119	        this.customerCode = customerCode;
120	    }
121	
122	    public String getHouseholdId() {
123	        return this.householdId;
124	    }
125	
126	    public void setHouseholdId(String householdId) {
127	        this.householdId = householdId;
128	    }
129	
130	    public Integer getNamesakeCount() {
131	        return this.namesakeCount;
132	    }
133	
134	    public void setNamesakeCount(Integer namesakeCount) {
135	        this.namesakeCount = namesakeCount;
136	    }
137	
138	    public Integer getHouseholdSize() {
139	        return this.householdSize;
140	    }
141	
142	    public void setHouseholdSize(Integer householdSize) {
143	        this.householdSize = householdSize;
144	    }
145	
146	    public boolean isBulkSignupWarning() {
147	        return this.bulkSignupWarning;
148	    }
149	
150	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
151	        this.bulkSignupWarning = bulkSignupWarning;
152	    }
153	
154	    protected Set<Pet> getPetsInternal() {
155	        if (this.pets == null) {
156	            this.pets = new HashSet<>();
157	        }
158	        return this.pets;
159	    }
160	
161	    protected void setPetsInternal(Set<Pet> pets) {
162	        this.pets = pets;
163	    }
164	
165	    public List<Pet> getPets() {
166	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
167	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
168	        return Collections.unmodifiableList(sortedPets);
169	    }
170	
171	    public void setPets(List<Pet> pets) {
172	        this.pets = new HashSet<>(pets);
173	    }
174	
175	    public void addPet(Pet pet) {
176	        getPetsInternal().add(pet);
177	        pet.setOwner(this);
178	    }
179	
180	    /**
181	     * Return the Pet with the given name, or null if none found for this Owner.
182	     *
183	     * @param name to test
184	     * @return true if pet name is already in use
185	     */
186	    public Pet getPet(String name) {
187	        return getPet(name, false);
188	    }
189	
190	    /**
191	     * Return the Pet with the given name, or null if none found for this Owner.
192	     *
193	     * @param name to test
194	     * @return true if pet name is already in use
195	     */
196	    public Pet getPet(String name, boolean ignoreNew) {
197	        name = name.toLowerCase();
198	        for (Pet pet : getPetsInternal()) {
199	            if (!ignoreNew || !pet.isNew()) {
200	                String compName = pet.getName();
201	                compName = compName.toLowerCase();
202	                if (compName.equals(name)) {
203	                    return pet;
204	                }
205	            }
206	        }
207	        return null;
208	    }
209	
210	    public Pet getPet(Integer petId) {
211	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
212	    }
213	
214	    @Override
215	    public String toString() {
216	        return new ToStringCreator(this)
217	
218	            .append("id", this.getId())
219	            .append("new", this.isNew())
220	            .append("lastName", this.getLastName())
221	            .append("firstName", this.getFirstName())
222	            .append("address", this.address)
223	            .append("city", this.city)
224	            .append("telephone", this.telephone)
225	            .toString();
226	    }
227	}
