9	/**
10	 * Turns a {@link DuplicateTelephoneException} into a 409 when a create-owner
11	 * telephone is already used by another owner.
12	 */
13	public class DuplicateTelephoneExceptionHandler {
14	
15	    public void handle(@Parameter DuplicateTelephoneException ex,
16	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
17	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.CONFLICT,
18	                "The telephone is already used by another owner");
19	        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(detail));
20	    }
